            const deniedEvent = { id: "evt-dynamodb-denied-" + Date.now(), eventTime: new Date().toISOString(), eventName: "DeleteItem", eventSource: "dynamodb.amazonaws.com", userIdentity: "assumed-role/Lambda-Payments-Role/orders-event-handler", resource: tableName, region: "eu-west-1", errorCode: "AccessDeniedException", detail: "DynamoDB DeleteItem denied because Lambda-Payments-Role lacks DynamoDBOrdersWrite." };
