          {screen==="Load Balancers" && selectedResource && loadBalancers.find(item=>item.id===selectedResource) && (()=>{const lb=loadBalancers.find(item=>item.id===selectedResource)!;return <div className="aws-sim-panel"><div className="aws-sim-panel-title"><div><h2>Load balancer details</h2><p>{lb.name} · {lb.id}</p></div><button onClick={()=>setSelectedResource(null)}>Close details</button></div><div className="aws-sim-tabs">{["Description","Listeners and rules","Network mapping","Security"].map(item=><button key={item} className={tab===item?"active":""} onClick={()=>setTab(item)}>{item}</button>)}</div>{tab==="Listeners and rules"?<div className="aws-sim-table-wrap"><table><thead><tr><th>Protocol:Port</th><th>Default action</th></tr></thead><tbody>{lb.listeners.map(listener=><tr key={listener.id}><td>{listener.protocol}:{listener.port}</td><td>Forward to {targetGroups.find(group=>group.id===listener.targetGroupId)?.name??listener.targetGroupId}</td></tr>)}</tbody></table></div>:tab==="Network mapping"?<div className="aws-sim-detail-grid"><p><b>VPC</b><br/>{lb.vpcId}</p><p><b>Subnets</b><br/>{lb.subnetIds.map(id=>subnets.find(item=>item.id===id)?.name??id).join(", ")}</p></div>:tab==="Security"?<div className="aws-sim-detail-grid"><p><b>Scheme</b><br/>{lb.scheme}</p><p><b>Security configuration</b><br/>Review attached security groups and listener configuration.</p></div>:<div className="aws-sim-detail-grid"><p><b>Type</b><br/>{lb.type==="application"?"Application Load Balancer":"Network Load Balancer"}</p><p><b>State</b><br/>{lb.state}</p><p><b>Scheme</b><br/>{lb.scheme}</p><p><b>DNS name</b><br/><span className="mono">{lb.dnsName}</span></p><p><b>VPC</b><br/>{lb.vpcId}</p><p><b>Listeners</b><br/>{lb.listeners.length}</p></div>}</div>;})()}
          {screen==="Target Groups" && selectedResource && targetGroups.find(item=>item.id===selectedResource) && (()=>{const group=targetGroups.find(item=>item.id===selectedResource)!;const health=evaluateAwsTargetGroupHealth(state,group.id);return <div className="aws-sim-panel"><div className="aws-sim-panel-title"><div><h2>Target group details</h2><p>{group.name} · {group.id}</p></div><button onClick={()=>setSelectedResource(null)}>Close details</button></div><div className="aws-sim-tabs">{["Targets","Health checks","Attributes"].map(item=><button key={item} className={tab===item?"active":""} onClick={()=>setTab(item)}>{item}</button>)}</div>{tab==="Targets"?<div className="aws-sim-table-wrap"><table><thead><tr><th>Instance ID / name</th><th>Port</th><th>Availability Zone</th><th>Health status</th></tr></thead><tbody>{group.targetInstanceIds.map(id=>{const target=instances.find(item=>item.id===id);return <tr key={id}><td>{target?.name??id}<small>{id}</small></td><td>{group.port}</td><td>{target?.availabilityZone??"—"}</td><td><span className={"aws-sim-status "+(health.healthy?"good":"bad")}>{health.healthy?"Healthy":"Unhealthy"}</span></td></tr>})}</tbody></table></div>:tab==="Health checks"?<div className="aws-sim-detail-grid"><p><b>Protocol</b><br/>{group.protocol}</p><p><b>Health check path</b><br/>{group.healthCheckPath}</p><p><b>Expected matcher</b><br/>{group.matcher}</p><p><b>Expected healthy path</b><br/>{group.healthyPath}</p></div>:<div className="aws-sim-detail-grid"><p><b>Target type</b><br/>Instance</p><p><b>Protocol:Port</b><br/>{group.protocol}:{group.port}</p><p><b>VPC</b><br/>{group.vpcId}</p><p><b>Load balancer association</b><br/>{loadBalancers.filter(lb=>lb.listeners.some(listener=>listener.targetGroupId===group.id)).map(lb=>lb.name).join(", ")||"No associated load balancer"}</p></div>}</div>;})()}
          {screen==="Lambda" && selectedResource && lambdaFunctions.find(item=>item.name===selectedResource) && (()=>{const fn=lambdaFunctions.find(item=>item.name===selectedResource)!;const history=lambdaInvocationHistory[fn.name]??[];const defaultCode=fn.runtime.startsWith("Python")?"import json\ndef handler(event, context):\n    print(json.dumps(event))\n    return {\"statusCode\": 200, \"body\": json.dumps({\"ok\": True})}":"exports.handler = async (event) => {\n  console.log(JSON.stringify(event));\n  return { statusCode: 200, body: JSON.stringify({ ok: true }) };\n};";const code=lambdaCodeDraftByName[fn.name]??lambdaCodeByName[fn.name]??defaultCode;return <div className="aws-sim-panel"><div className="aws-sim-panel-title"><div><h2>{fn.name}</h2><p>{fn.runtime} · {fn.handler} · {fn.state==="active"?"Active":"Inactive"}</p></div><div className="aws-sim-toolbar-actions"><button onClick={()=>{setLambdaConfigDraft({name:fn.name,runtime:fn.runtime,handler:fn.handler,roleName:fn.roleName,timeoutSeconds:String(fn.timeoutSeconds),memoryMb:String(fn.memoryMb),description:(fn as typeof fn & {description?:string}).description??"",environmentText:Object.entries(fn.environment).map(([key,value])=>key+"="+value).join("\n"),vpcSubnetIds:[...fn.vpcSubnetIds],securityGroupIds:[...fn.securityGroupIds]});setLambdaConfigError("");setTab("Configuration");}}>Edit configuration</button><button onClick={()=>setSelectedResource(null)}>Close</button></div></div><div className="aws-sim-tabs">{["Code","Test","Monitor","Configuration","Permissions"].map(item=><button key={item} className={tab===item?"active":""} onClick={()=>setTab(item)}>{item}</button>)}</div>{tab==="Code"?<><div className="aws-sim-detail-grid"><p><b>Code source</b><br/>Inline editor · {fn.runtime}</p><p><b>Last modified</b><br/>Local simulator state</p><p><b>Handler</b><br/><span className="mono">{fn.handler}</span></p></div><label style={{display:"block",fontWeight:700,marginTop:12}}>Function code<textarea aria-label="Lambda function code" rows={14} spellCheck={false} value={code} onChange={event=>{setLambdaCodeDraftByName(current=>({...current,[fn.name]:event.target.value}));setLambdaCodeDirty(true);}} style={{width:"100%",fontFamily:"monospace",whiteSpace:"pre",marginTop:6}} /></label><div className="aws-sim-editor-actions"><button onClick={()=>{setLambdaCodeDraftByName(current=>({...current,[fn.name]:defaultCode}));setLambdaCodeDirty(true);}}>Reset sample code</button><button className="primary" onClick={()=>{setLambdaCodeByName(current=>({...current,[fn.name]:lambdaCodeDraftByName[fn.name]??code}));setLambdaCodeDraftByName(current=>{const next={...current};delete next[fn.name];return next;});setLambdaCodeDirty(false);setState(current=>({...current,cloudTrailEvents:[{id:"evt-lambda-code-"+Date.now(),eventTime:new Date().toISOString(),eventName:"UpdateFunctionCode",eventSource:"lambda.amazonaws.com",userIdentity:"simulated-console-user",resource:fn.name,region:"eu-west-1",errorCode:null,detail:"Function code deployed in the simulator."},...(current.cloudTrailEvents??[])].slice(0,100)}));notify("Function code deployed in the simulator.");}}>Deploy</button></div><p className="aws-sim-muted">Code is saved locally. This sandbox does not execute arbitrary handler source; invocation results are simulated using function state and IAM permissions.</p></>:tab==="Test"?<><div className="aws-sim-detail-grid"><p><b>Test event</b><br/>JSON event payload</p><p><b>Execution role</b><br/>{fn.roleName}</p><p><b>Timeout</b><br/>{fn.timeoutSeconds} seconds</p></div><label style={{display:"block",fontWeight:700,marginTop:12}}>Event JSON<textarea aria-label="Lambda test event JSON" rows={10} spellCheck={false} value={lambdaTestEventDraft||lambdaTestEventByName[fn.name]||JSON.stringify({httpMethod:"GET",path:"/health",body:null},null,2)} onChange={event=>{setLambdaTestEventDraft(event.target.value);setLambdaTestEventByName(current=>({...current,[fn.name]:event.target.value}));setLambdaTestError("");}} style={{width:"100%",fontFamily:"monospace",whiteSpace:"pre",marginTop:6}} /></label>{lambdaTestError&&<p className="aws-sim-error" role="alert">{lambdaTestError}</p>}<div className="aws-sim-editor-actions"><button onClick={()=>{setLambdaTestEventDraft(JSON.stringify({httpMethod:"GET",path:"/health",body:null},null,2));setLambdaTestEventByName(current=>({...current,[fn.name]:JSON.stringify({httpMethod:"GET",path:"/health",body:null},null,2)}));setLambdaTestError("");}}>Load sample event</button><button className="primary" onClick={()=>{const raw=lambdaTestEventDraft||lambdaTestEventByName[fn.name]||JSON.stringify({httpMethod:"GET",path:"/health",body:null});let parsed:unknown;try{parsed=JSON.parse(raw);}catch{setLambdaTestError("Event must be valid JSON.");return;}const result=invokeAwsLambdaFunction(state,fn.name);setState(result.state);const time=new Date().toISOString();const requestId="sim-"+Math.random().toString(36).slice(2,14);const response=JSON.stringify(result.success?{statusCode:200,body:JSON.stringify({ok:true,functionName:fn.name,received:parsed})}:{errorType:"AccessDeniedException",errorMessage:result.detail},null,2);const item={time,success:result.success,requestId,detail:result.detail,event:JSON.stringify(parsed,null,2),response};setLambdaLastResult({functionName:fn.name,...item});setLambdaInvocationHistory(current=>({...current,[fn.name]:[item,...(current[fn.name]??[])].slice(0,30)}));setLambdaTestEventByName(current=>({...current,[fn.name]:raw}));setLambdaTestEventDraft(raw);setLambdaTestError("");notify(result.success?"Execution succeeded":"Execution failed");}}>Test</button></div>{lambdaLastResult?.functionName===fn.name&&<div className="aws-sim-editor"><h3>Execution result · {lambdaLastResult.success?"Succeeded":"Failed"}</h3><p>Request ID: <span className="mono">{lambdaLastResult.requestId}</span> · {new Date(lambdaLastResult.time).toLocaleString()}</p><pre className="aws-sim-policy-json">{lambdaLastResult.response}</pre><p>{lambdaLastResult.detail}</p></div>}</>:tab==="Monitor"?<><div className="aws-sim-detail-grid"><p><b>Invocations</b><br/>{history.length} recorded in this browser</p><p><b>Errors</b><br/>{fn.errorCount}</p><p><b>Successes</b><br/>{history.filter(item=>item.success).length}</p><p><b>Log group</b><br/><span className="mono">/aws/lambda/{fn.name}</span></p></div><div className="aws-sim-section-heading inside"><h3>Recent invocations</h3><button onClick={()=>go("CloudWatch")}>Open CloudWatch ↗</button></div><div className="aws-sim-table-wrap"><table><thead><tr><th>Timestamp</th><th>Request ID</th><th>Status</th><th>Details</th></tr></thead><tbody>{history.map(item=><tr key={item.requestId}><td>{new Date(item.time).toLocaleString()}</td><td className="mono">{item.requestId}</td><td><span className={"aws-sim-status "+(item.success?"good":"bad")}>{item.success?"Succeeded":"Failed"}</span></td><td>{item.detail}</td></tr>)}{history.length===0&&<tr><td colSpan={4}>No invocations recorded in this browser session.</td></tr>}</tbody></table></div><div className="aws-sim-editor"><h3>Recent log events</h3><pre className="aws-sim-policy-json">{history.slice(0,5).map(item=>`${item.time} ${item.success?"REPORT RequestId:":"ERROR RequestId:"} ${item.requestId} ${item.detail}`).join("\n")||"No log events yet. Run a test invocation to generate simulated log entries."}</pre></div></>:tab==="Configuration"?<><div className="aws-sim-editor"><div className="aws-sim-panel-title"><div><h3>Basic configuration</h3><p>Runtime, handler, role, resources and environment variables</p></div>{!lambdaConfigDraft&&<button onClick={()=>{setLambdaConfigDraft({name:fn.name,runtime:fn.runtime,handler:fn.handler,roleName:fn.roleName,timeoutSeconds:String(fn.timeoutSeconds),memoryMb:String(fn.memoryMb),description:(fn as typeof fn & {description?:string}).description??"",environmentText:Object.entries(fn.environment).map(([key,value])=>key+"="+value).join("\n"),vpcSubnetIds:[...fn.vpcSubnetIds],securityGroupIds:[...fn.securityGroupIds]});setLambdaConfigError("");}}>Edit</button>}</div>{lambdaConfigDraft?.name===fn.name?<><div className="aws-sim-form-grid"><label>Runtime<select value={lambdaConfigDraft.runtime} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,runtime:event.target.value})}>{["Node.js 22.x","Node.js 20.x","Python 3.13","Python 3.12","Python 3.11","Java 21",".NET 8","Ruby 3.4"].map(value=><option key={value}>{value}</option>)}</select></label><label>Handler<input value={lambdaConfigDraft.handler} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,handler:event.target.value})}/></label><label>Execution role<select value={lambdaConfigDraft.roleName} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,roleName:event.target.value})}>{state.iamRoles.map(role=><option key={role.name} value={role.name}>{role.name}</option>)}</select></label><label>Timeout (seconds)<input type="number" min="1" max="900" value={lambdaConfigDraft.timeoutSeconds} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,timeoutSeconds:event.target.value})}/></label><label>Memory (MB)<select value={lambdaConfigDraft.memoryMb} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,memoryMb:event.target.value})}>{[128,256,512,1024,1769,2048,3008,4096,8192,10240].map(value=><option key={value} value={String(value)}>{value} MB</option>)}</select></label><label>Description<input value={lambdaConfigDraft.description} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,description:event.target.value})}/></label><label className="wide">Environment variables (KEY=value, one per line)<textarea rows={4} value={lambdaConfigDraft.environmentText} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,environmentText:event.target.value})}/></label><label className="wide">VPC subnets<select multiple value={lambdaConfigDraft.vpcSubnetIds} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,vpcSubnetIds:Array.from(event.target.selectedOptions).map(option=>option.value)})}>{subnets.map(item=><option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select></label><label className="wide">Security groups<select multiple value={lambdaConfigDraft.securityGroupIds} onChange={event=>setLambdaConfigDraft({...lambdaConfigDraft,securityGroupIds:Array.from(event.target.selectedOptions).map(option=>option.value)})}>{state.securityGroups.map(item=><option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select></label></div>{lambdaConfigError&&<p className="aws-sim-error" role="alert">{lambdaConfigError}</p>}<div className="aws-sim-editor-actions"><button onClick={()=>{setLambdaConfigDraft(null);setLambdaConfigError("");}}>Cancel</button><button className="primary" onClick={()=>{const timeout=Number(lambdaConfigDraft.timeoutSeconds),memory=Number(lambdaConfigDraft.memoryMb),handler=lambdaConfigDraft.handler.trim();const env:Record<string,string>={};for(const line of lambdaConfigDraft.environmentText.split(/\r?\n/)){if(!line.trim())continue;const split=line.indexOf("=");if(split<1){setLambdaConfigError("Environment variables must use KEY=value, one per line.");return;}const key=line.slice(0,split).trim();if(!/^[A-Za-z][A-Za-z0-9_]+$/.test(key)){setLambdaConfigError("Environment variable names must start with a letter and contain only letters, numbers, and underscores.");return;}env[key]=line.slice(split+1);}if(!handler){setLambdaConfigError("Enter a handler.");return;}if(!Number.isInteger(timeout)||timeout<1||timeout>900){setLambdaConfigError("Timeout must be between 1 and 900 seconds.");return;}if(!Number.isInteger(memory)||memory<128||memory>10240){setLambdaConfigError("Memory must be between 128 and 10240 MB.");return;}setState(current=>({...current,lambdaFunctions:(current.lambdaFunctions??[]).map(item=>item.name===fn.name?{...item,runtime:lambdaConfigDraft.runtime,handler,roleName:lambdaConfigDraft.roleName,timeoutSeconds:timeout,memoryMb:memory,environment:env,vpcSubnetIds:lambdaConfigDraft.vpcSubnetIds,securityGroupIds:lambdaConfigDraft.securityGroupIds,...({description:lambdaConfigDraft.description} as object)}:item),cloudTrailEvents:[{id:"evt-lambda-config-"+Date.now(),eventTime:new Date().toISOString(),eventName:"UpdateFunctionConfiguration",eventSource:"lambda.amazonaws.com",userIdentity:"simulated-console-user",resource:fn.name,region:"eu-west-1",errorCode:null,detail:"Function configuration updated in the simulator."},...(current.cloudTrailEvents??[])].slice(0,100)}));setLambdaConfigDraft(null);setLambdaConfigError("");notify("Function configuration updated.");}}>Save</button></div></>:<div className="aws-sim-detail-grid"><p><b>Runtime</b><br/>{fn.runtime}</p><p><b>Handler</b><br/>{fn.handler}</p><p><b>Execution role</b><br/>{fn.roleName}</p><p><b>Timeout</b><br/>{fn.timeoutSeconds} seconds</p><p><b>Memory</b><br/>{fn.memoryMb} MB</p><p><b>Ephemeral storage</b><br/>512 MB</p><p><b>Environment variables</b><br/>{Object.entries(fn.environment).map(([key,value])=>key+"="+value).join(", ")||"None"}</p><p><b>VPC</b><br/>{fn.vpcSubnetIds.length?fn.vpcSubnetIds.map(id=>subnets.find(item=>item.id===id)?.name??id).join(", "):"Not configured"}</p></div>}</div></>:<div className="aws-sim-editor"><h3>Execution role</h3><p>{fn.roleName}</p><p>Trust principal: {state.iamRoles.find(role=>role.name===fn.roleName)?.trustedService??"Role not found"}</p><p>Required policy: {fn.requiredPolicy??"No service-specific policy configured"}</p><div className="aws-sim-related"><button onClick={()=>{go("IAM");setTab("Roles");setSelectedResource(fn.roleName);}}>Open role in IAM ↗</button></div></div>}</div>;})()}
          {screen==="Glue" && selectedResource && glueJobs.find(item=>item.name===selectedResource) && (()=>{const job=glueJobs.find(item=>item.name===selectedResource)!;return <div className="aws-sim-panel"><div className="aws-sim-panel-title"><div><h2>Job details</h2><p>{job.name}</p></div><button onClick={()=>setSelectedResource(null)}>Close details</button></div><div className="aws-sim-tabs">{["Job details","Runs","Monitoring"].map(item=><button key={item} className={tab===item?"active":""} onClick={()=>setTab(item)}>{item}</button>)}</div><div className="aws-sim-detail-grid"><p><b>Last run status</b><br/>{job.state}</p><p><b>Last run time</b><br/>{new Date(job.lastRunTime).toLocaleString()}</p><p><b>Script / source</b><br/>{job.sourceBucketName}/{job.sourcePrefix}</p><p><b>Target</b><br/>{job.targetBucketName}/{job.targetPrefix}</p><p><b>Bookmark</b><br/>{job.bookmarkEnabled?"Enabled":"Disabled"}</p><p><b>Records read / written</b><br/>{job.recordsRead.toLocaleString()} / {job.recordsWritten.toLocaleString()}</p><p><b>Latest error</b><br/>{job.errorMessage||"No error reported"}</p></div><div className="aws-sim-related"><b>Actions</b><button onClick={()=>runGlueJob(job.name)}>Run job ↻</button><button onClick={()=>go("CloudWatch")}>CloudWatch ↗</button><button onClick={()=>go("CloudTrail")}>CloudTrail ↗</button></div></div>;})()}
